import 'package:flutter/material.dart';
import 'package:image_picker/image_picker.dart';
import '../../services/api_service.dart';
class AddItemScreen extends StatefulWidget{const AddItemScreen({super.key});@override State<AddItemScreen> createState()=>_S();}
class _S extends State<AddItemScreen>{final name=TextEditingController(),category=TextEditingController(),color=TextEditingController();XFile? image;bool busy=false;Future<void> pick(ImageSource s)async{final x=await ImagePicker().pickImage(source:s,imageQuality:85,maxWidth:1600);if(x!=null)setState(()=>image=x);}Future<void> save()async{if(name.text.trim().length<2)return;setState(()=>busy=true);try{await ApiService().saveClothing({'name':name.text,'category':category.text,'color':color.text},image:image);if(mounted)Navigator.pop(context,true);}catch(e){if(mounted)ScaffoldMessenger.of(context).showSnackBar(SnackBar(content:Text('$e')));}finally{if(mounted)setState(()=>busy=false);}}@override Widget build(BuildContext c)=>Scaffold(appBar:AppBar(title:const Text('Add clothing')),body:ListView(padding:const EdgeInsets.all(20),children:[Container(height:220,decoration:BoxDecoration(color:Colors.grey.shade100,borderRadius:BorderRadius.circular(24)),child:image==null?const Icon(Icons.add_a_photo_outlined,size:54):FutureBuilder(future:image!.readAsBytes(),builder:(c,s)=>s.hasData?ClipRRect(borderRadius:BorderRadius.circular(24),child:Image.memory(s.data!,fit:BoxFit.cover)):const Center(child:CircularProgressIndicator()))),const SizedBox(height:12),Row(children:[Expanded(child:OutlinedButton.icon(onPressed:()=>pick(ImageSource.camera),icon:const Icon(Icons.camera_alt_outlined),label:const Text('Camera'))),const SizedBox(width:10),Expanded(child:OutlinedButton.icon(onPressed:()=>pick(ImageSource.gallery),icon:const Icon(Icons.photo_library_outlined),label:const Text('Gallery')))]),const SizedBox(height:18),TextField(controller:name,decoration:const InputDecoration(labelText:'Item name')),const SizedBox(height:12),TextField(controller:category,decoration:const InputDecoration(labelText:'Category')),const SizedBox(height:12),TextField(controller:color,decoration:const InputDecoration(labelText:'Color')),const SizedBox(height:22),FilledButton(onPressed:busy?null:save,child:Text(busy?'Saving...':'Save to wardrobe'))]));}
